/**
 * @summary Render an edited working copy as MP4
 */

export const exportEditedVideoBodyClipsItemStartMin = 0;

export const exportEditedVideoBodyClipsItemEndExclusiveMin = 0;

export const exportEditedVideoBodyClipsMax = 20;

export const exportEditedVideoBodyVolumeMin = 0;
export const exportEditedVideoBodyVolumeMax = 2;

export const exportEditedVideoBodyTextsItemTextMax = 240;

export const exportEditedVideoBodyTextsItemStartMin = 0;

export const exportEditedVideoBodyTextsItemEndExclusiveMin = 0;

export const exportEditedVideoBodyTextsItemXMin = 0;
export const exportEditedVideoBodyTextsItemXMax = 100;

export const exportEditedVideoBodyTextsItemYMin = 0;
export const exportEditedVideoBodyTextsItemYMax = 100;

export const exportEditedVideoBodyTextsItemSizeMin = 12;
export const exportEditedVideoBodyTextsItemSizeMax = 96;

export const exportEditedVideoBodyTextsItemColorRegExp = new RegExp('^#[0-9a-fA-F]{6}$');
export const exportEditedVideoBodyTextsMax = 20;



export const ExportEditedVideoBody = zod.object({
  "analysisId": zod.number().int().min(1),
  "clips": zod.array(zod.object({
  "start": zod.number().min(exportEditedVideoBodyClipsItemStartMin),
  "end": zod.number().gt(exportEditedVideoBodyClipsItemEndExclusiveMin),
  "transition": zod.enum(['none', 'fade'])
})).min(1).max(exportEditedVideoBodyClipsMax),
  "filter": zod.enum(['none', 'grayscale', 'warm', 'cool', 'contrast']),
  "volume": zod.number().min(exportEditedVideoBodyVolumeMin).max(exportEditedVideoBodyVolumeMax),
  "muted": zod.boolean(),
  "texts": zod.array(zod.object({
  "text": zod.string().min(1).max(exportEditedVideoBodyTextsItemTextMax),
  "start": zod.number().min(exportEditedVideoBodyTextsItemStartMin),
  "end": zod.number().gt(exportEditedVideoBodyTextsItemEndExclusiveMin),
  "x": zod.number().min(exportEditedVideoBodyTextsItemXMin).max(exportEditedVideoBodyTextsItemXMax),
  "y": zod.number().min(exportEditedVideoBodyTextsItemYMin).max(exportEditedVideoBodyTextsItemYMax),
  "size": zod.number().int().min(exportEditedVideoBodyTextsItemSizeMin).max(exportEditedVideoBodyTextsItemSizeMax),
  "color": zod.string().regex(exportEditedVideoBodyTextsItemColorRegExp)
})).max(exportEditedVideoBodyTextsMax)
})

export const ExportEditedVideoResponse = zod.unknown()


